package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testNull() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testBlank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testHexInteger() {
        assertTrue(NumberUtils.createNumber("0x123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("0X123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("#123") instanceof Integer);
        assertTrue(NumberUtils.createNumber("-#123") instanceof Integer);
    }

    @Test
    public void testHexLong() {
        // hexDigits > 8
        assertTrue(NumberUtils.createNumber("0x123456789") instanceof Long);
        assertTrue(NumberUtils.createNumber("-0x123456789") instanceof Long);
    }

    @Test
    public void testHexBigInteger() {
        // hexDigits > 16
        assertTrue(NumberUtils.createNumber("0x12345678901234567") instanceof BigInteger);
    }

    @Test
    public void testIntegerTypes() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123l"));
        // BigInteger fallback for Long suffix
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);
    }

    @Test
    public void testFloatSuffix() {
        assertTrue(NumberUtils.createNumber("123.45f") instanceof Float);
        assertTrue(NumberUtils.createNumber("123.45F") instanceof Float);
    }

    @Test
    public void testDoubleSuffix() {
        assertTrue(NumberUtils.createNumber("123.45d") instanceof Double);
        assertTrue(NumberUtils.createNumber("123.45D") instanceof Double);
    }

    @Test
    public void testDecimalPrecision() {
        // numDecimals <= 7 -> Float
        assertTrue(NumberUtils.createNumber("1.234567") instanceof Float);
        // 8 <= numDecimals <= 16 -> Double
        assertTrue(NumberUtils.createNumber("1.12345678") instanceof Double);
        // numDecimals > 16 -> BigDecimal
        assertTrue(NumberUtils.createNumber("1.12345678901234567") instanceof BigDecimal);
    }

    @Test
    public void testScientificNotation() {
        assertTrue(NumberUtils.createNumber("1e2") instanceof Float);
        assertTrue(NumberUtils.createNumber("1.2E3") instanceof Double);
    }

    @Test
    public void testInvalidSuffix() {
        try {
            NumberUtils.createNumber("123.45z");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }
    }

    @Test
    public void testInvalidExponentPosition() {
        try {
            NumberUtils.createNumber("1.2e"); // expPos logic check
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }
    }

    @Test
    public void testFloatingPointEdgeCases() {
        // Test allZeros logic for Float/Double fallback
        // "0.0000000000000001f" -> if it evaluates to 0.0f but isn't all zeros, it should fall through
        assertTrue(NumberUtils.createNumber("0.0000000000000000000000001f") instanceof Double);

        // Test Infinite
        assertTrue(NumberUtils.createNumber("1e40f") instanceof Double); // Float overflow -> Double
    }

    @Test
    public void testNegativeNumbers() {
        assertEquals(Integer.valueOf(-123), NumberUtils.createNumber("-123"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123L"));
        assertTrue(NumberUtils.createNumber("-0x123") instanceof Integer);
    }

    @Test
    public void testDecimalOnly() {
        assertTrue(NumberUtils.createNumber("123.") instanceof Float);
    }
}
